// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the from address, an amount, and a single recipient index selection
    function testFuzz_property(address from, uint256 v, uint8 recipientChoice) public {
        // keep recipientChoice small so we can build a one-element array deterministically
        // but still allow fuzzing over many values
        address[] memory tos = new address[](1);
        // create a recorder callee that will record the exact decoded arguments of transferFrom
        Recorder r = new Recorder();

        // choose a recipient address derived from recipientChoice to keep it a valid non-zero address
        // we avoid zero address for clarity, but allow any address otherwise
        address to = address(uint160(uint256(keccak256(abi.encodePacked(recipientChoice, block.timestamp)))));
        tos[0] = to;

        // ensure tos length > 0 (already 1) and v can be any uint
        // call c.transfer and observe whether it succeeded (did not revert)
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: the correct contract C always calls Recorder.transferFrom(from, to, v)
        // i.e., the callee's recorded `from` should equal the `from` we passed in and `to` should equal tos[0].
        // The mutant swaps the first two args, so for some inputs the callee would see swapped addresses.
        // We assert that when the external call succeeded (ok==true) the recorder observed the same from/to we passed.
        // This property holds for the reference implementation for all admissible inputs, but the mutant will violate it for inputs where behavior depends on the order.

        // If the external call reverted, the recorder will not have recorded a successful call; in that case ok==false
        // and we cannot inspect arguments. We only assert the invariant in the successful-call case.
        if (ok) {
            // check recorder recorded exactly one call and that its decoded args match (from, to, v)
            assertTrue(r.callCount() == 1 && r.lastFrom() == from && r.lastTo() == to && r.lastV() == v);
        } else {
            // If call reverted, then recorder should have no successful recordings
            assertTrue(r.callCount() == 0);
        }
    }
}

// Recorder matches the exact signature: transferFrom(address,address,uint256)
contract Recorder {
    uint public calls;
    address public _lastFrom;
    address public _lastTo;
    uint public _lastV;

    // Expose the same function selector that C encodes with
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        _lastFrom = from;
        _lastTo = to;
        _lastV = v;
        return true;
    }

    // getters that the test will use
    function callCount() external view returns (uint) { return calls; }
    function lastFrom() external view returns (address) { return _lastFrom; }
    function lastTo() external view returns (address) { return _lastTo; }
    function lastV() external view returns (uint) { return _lastV; }
}
